create or replace function private.invoke_historical_player_evidence_v01(p_season text default '2024-2025') returns bigint language plpgsql security definer set search_path=private,public,vault,net,pg_temp as $$ declare v_token text; v_request_id bigint; begin if p_season <> '2024-2025' then raise exception 'Only 2024-2025 supported'; end if; select decrypted_secret into v_token from vault.decrypted_secrets where name='FOOTBALL_ENGINE_ADMIN_TOKEN' order by created_at desc limit 1; if v_token is null then raise exception 'Engine admin token missing'; end if; select net.http_post(url:='https://knooiwezzsxcwhtjtdap.supabase.co/functions/v1/ingest-historical-player-evidence',body:=jsonb_build_object('season',p_season),headers:=jsonb_build_object('Content-Type','application/json','x-engine-token',v_token),timeout_milliseconds:=60000) into v_request_id; return v_request_id; end $$;
revoke all on function private.invoke_historical_player_evidence_v01(text) from public,anon,authenticated;
grant execute on function private.invoke_historical_player_evidence_v01(text) to service_role;
